264: export function gearStats(state) {
265:   const total = {};
266:   for (const slot of GEAR_SLOTS) {
267:     const item = equippedItem(state, slot.id);
268:     if (!item) continue;
269:     for (const [key, value] of Object.entries(item.stats || {})) {
270:       total[key] = (total[key] || 0) + (Number(value) || 0);
271:     }
272:   }
273:   return total;
274: }
275: 
276: export function gearScore(item) {
277:   const stats = item?.stats || {};
278:   let score = 0;
279:   for (const [key, value] of Object.entries(stats)) {
280:     if (PCT_STATS.has(key)) score += value * 100;
281:     else if (key === 'hp') score += value * 0.4;
282:     else score += value * 2;
283:   }
284:   return Math.round(score);
285: }
