287: export function gearStatText(key, value) {
288:   const label = GEAR_STAT_LABELS[key] || key.toUpperCase();
289:   if (PCT_STATS.has(key)) return `${label} +${(value * 100).toFixed(1)}%`;
290:   return `${label} +${Math.round(value)}`;
291: }
