302: export function lootRunCost(state) {
303:   const level = Math.max(1, state?.level || 1);
304:   const zones = Math.max(1, state?.combat?.unlocked || 1);
305:   return Math.ceil(35 + level * 10 + (zones - 1) * 40);
306: }
