308: function rollRarity(state, boss = false) {
309:   const bonus = Math.min(26,
310:     (state?.level || 1) * 0.35
311:     + (state?.combat?.unlocked || 1) * 2
312:     + (state?.shards || 0) * 0.6
313:     + (boss ? 8 : 0));
314:   const roll = Math.random() * 100;
315:   if (roll < 1 + bonus * 0.12) return RARITIES[4];
316:   if (roll < 4 + bonus * 0.32) return RARITIES[3];
317:   if (roll < 14 + bonus * 0.8) return RARITIES[2];
318:   if (roll < 38 + bonus * 0.4) return RARITIES[1];
319:   return RARITIES[0];
320: }
321: 
322: function pickSlot() {
323:   const roll = Math.random() * 100;
324:   if (roll < 28) return 'weapon';
325:   if (roll < 49) return 'tool';
326:   if (roll < 71) return 'armor';
327:   if (roll < 87) return 'helm';
328:   return 'charm';
329: }
330: 
331: export function makeLootItem(state, opts = {}) {
332:   const slotId = opts.slot || pickSlot();
333:   const slot = GEAR_SLOT_MAP[slotId];
334:   if (!slot) return null;
335:   const rarity = opts.rarity ? (RARITY_MAP[opts.rarity] || RARITIES[0]) : rollRarity(state, !!opts.boss);
336:   const level = Math.max(1, Math.floor(
337:     (state?.level || 1) * 0.8
338:     + (state?.combat?.unlocked || 1) * 2
339:     + (opts.boss ? 3 : 0)
340:     + Math.random() * 2
341:   ));
342: 
343:   let classId = null;
344:   let baseName;
345:   if (slotId === 'weapon') {
346:     const weapon = COMBAT_WEAPONS[Math.floor(Math.random() * COMBAT_WEAPONS.length)];
347:     classId = weapon.id;
348:     baseName = weapon.name;
349:   } else if (slotId === 'tool') {
350:     const tool = MINING_TOOLS[Math.floor(Math.random() * MINING_TOOLS.length)];
351:     classId = tool.id;
352:     baseName = tool.name;
353:   } else {
354:     const names = LOOT_BASE_NAMES[slotId];
355:     baseName = names[Math.min(names.length - 1, rarity.rank)];
356:   }
357: 
358:   const pool = [...LOOT_AFFIXES[slotId]].sort(() => Math.random() - 0.5).slice(0, rarity.affixes);
359:   const scale = (0.75 + Math.min(60, level) * 0.035) * (1 + rarity.rank * 0.12);
360:   const stats = {};
361:   for (const affix of pool) {
362:     const base = affix.min + Math.random() * (affix.max - affix.min);
363:     const value = base * scale * (affix.flat ? 1 + level * 0.08 : 1);
364:     stats[affix.key] = affix.flat ? Math.max(1, Math.round(value)) : Math.round(value * 1000) / 1000;
365:   }
366: 
367:   return {
368:     id: `loot_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`,
369:     slot: slotId,
370:     rarity: rarity.id,
371:     name: `${rarity.prefix} ${baseName}`,
372:     level,
373:     classId,
374:     stats,
375:   };
376: }
