378: export function sanitizeLootItem(raw) {
379:   if (!raw || typeof raw !== 'object') return null;
380:   const slot = GEAR_SLOT_MAP[raw.slot];
381:   if (!slot) return null;
382:   const rarity = RARITY_MAP[raw.rarity] || RARITIES[0];
383:   const stats = {};
384:   for (const [key, value] of Object.entries(raw.stats || {})) {
385:     if (!(key in GEAR_STAT_LABELS)) continue;
386:     const n = Number(value);
387:     if (Number.isFinite(n) && n > 0) stats[key] = n;
388:   }
389:   if (!Object.keys(stats).length) return null;
390:   const classId = (slot.id === 'weapon' && COMBAT_WEAPON_MAP[raw.classId])
391:     ? raw.classId
392:     : (slot.id === 'tool' && MINING_TOOL_MAP[raw.classId]) ? raw.classId : null;
393:   return {
394:     id: String(raw.id || `loot_${Math.random().toString(36).slice(2, 9)}`),
395:     slot: slot.id,
396:     rarity: rarity.id,
397:     name: String(raw.name || `${rarity.prefix} ${slot.name}`),
398:     level: Math.max(1, Math.floor(Number(raw.level) || 1)),
399:     classId,
400:     stats,
401:   };
402: }
