756: /* ── formatting helpers ────────────────────────────────────── */
757: export function fmt(n, digits = 0) {
758:   if (!isFinite(n)) return '∞';
759:   const abs = Math.abs(n);
760:   if (abs < 1000) {
761:     if (abs === 0) return '0';
762:     if (abs < 10 && digits > 0) return n.toFixed(digits);
763:     if (abs < 100 && digits > 0 && n % 1 !== 0) return n.toFixed(1);
764:     return String(Math.floor(n));
765:   }
766:   const units = ['K', 'M', 'B', 'T', 'Qa', 'Qi', 'Sx', 'Sp'];
767:   let i = -1;
768:   let v = n;
769:   while (Math.abs(v) >= 1000 && i < units.length - 1) { v /= 1000; i++; }
770:   const dec = Math.abs(v) >= 100 ? 0 : Math.abs(v) >= 10 ? 1 : 2;
771:   return `${v.toFixed(dec).replace(/\.0+$/, '')}${units[i]}`;
772: }
