205: export function resetProgress(state) {
206:   const fresh = defaultState();
207:   // Prestige wipes the run, but the survivor's RPG progression and outfits persist.
208:   fresh.shards = state.shards;
209:   fresh.sound = state.sound;
210:   fresh.autoMine = !!state.autoMine;
211:   fresh.stats.startedAt = state.stats.startedAt;
212:   fresh.level = state.level;
213:   fresh.xp = state.xp;
214:   fresh.points = state.points;
215:   fresh.perkPoints = state.perkPoints;
216:   fresh.attributes = { ...state.attributes };
217:   fresh.perks = { ...state.perks };
218:   fresh.outfits = { ...state.outfits };
219:   // Schematics are knowledge, not hardware: unlocked tools and weapons survive.
220:   fresh.tools = { ...state.tools };
221:   fresh.weapons = { ...state.weapons };
222:   fresh.equippedTool = state.equippedTool;
223:   fresh.equippedWeapon = state.equippedWeapon;
224:   // Salvage and fitted gear are physical, but the survivor keeps their pack.
225:   fresh.inventory = (state.inventory || []).map((item) => ({ ...item, stats: { ...item.stats } }));
226:   fresh.loadout = { ...state.loadout };
227:   fresh.combat.hp = playerStats(fresh).maxHp;
228:   return fresh;
229: }
