310:   bind() {
311:     document.addEventListener('click', (e) => {
312:       const target = e.target.closest('[data-action]');
313:       if (target) {
314:         const action = target.dataset.action;
315:         const index = Number(target.dataset.index || 0);
316:         this.dispatch(action, index, target);
317:         return;
318:       }
319:       const tab = e.target.closest('[data-tab]');
320:       if (tab) {
321:         this.setTab(tab.dataset.tab);
322:         return;
323:       }
324:       if (e.target.closest('#soundBtn')) {
325:         this.game.toggleSound();
326:         return;
327:       }
328:       if (e.target.closest('#resetBtn')) {
329:         this.game.confirmReset();
330:       }
331:     });
332: 
333:     document.addEventListener('keydown', (e) => {
334:       if (e.repeat) return;
335:       if (!$('modal').hidden) return;
336:       if (e.code === 'Space') {
337:         e.preventDefault();
338:         if (document.getElementById('app').dataset.tab === 'mine' || window.innerWidth > 980) this.game.strikeMine();
339:       } else if (e.key === 'f' || e.key === 'F') {
340:         if (document.getElementById('app').dataset.tab === 'fight' || window.innerWidth > 980) this.game.attack();
341:       }
342:     });
343: 
344:     window.addEventListener('resize', () => {
345:       this.game.mineRenderer?.resize();
346:       this.game.combatRenderer?.resize();
347:     });
348: 
349:     // The scene canvases are the primary input on touch devices.
350:     $('mineScene')?.addEventListener('pointerdown', (e) => {
351:       if (e.target.closest('[data-action]')) return;
352:       this.game.strikeMine();
353:     });
354:     $('arena')?.addEventListener('pointerdown', (e) => {
355:       if (e.target.closest('[data-action]') || e.target.closest('.death-banner')) return;
356:       this.game.attack();
357:     });
358:   }
359: 
360:   dispatch(action, index, target) {
361:     const g = this.game;
362:     switch (action) {
363:       case 'strike': g.strikeMine(); break;
364:       case 'attack': g.attack(); break;
365:       case 'auto': g.toggleAuto(); break;
366:       case 'automine': g.toggleAutoMine(); break;
367:       case 'equiptool': g.equipTool(target?.dataset.id); break;
368:       case 'equipweapon': g.equipWeapon(target?.dataset.id); break;
369:       case 'gear': this.openGear(); break;
370:       case 'salvagerun': g.salvageRun(); break;
371:       case 'equiploot': g.equipLoot(target?.dataset.id); break;
372:       case 'unequip': g.unequipSlot(target?.dataset.slot); break;
373:       case 'scraploot': g.scrapLoot(target?.dataset.id); break;
374:       case 'pickaxe': g.buyPickaxe(); break;
375:       case 'crew': g.buyCrew(); break;
376:       case 'weapon': g.buyWeapon(); break;
377:       case 'armor': g.buyArmor(); break;
378:       case 'stim': g.buyStim(); break;
379:       case 'drill': g.buyDrill(index); break;
380:       case 'layer': g.selectLayer(index); break;
381:       case 'zone': g.selectZone(index); break;
382:       case 'outfit': g.buyOutfit(index); break;
383:       case 'attr': g.spendPoint(target?.dataset.id); break;
384:       case 'perks': g.openPerks(); break;
385:       case 'respec': g.respec(); break;
386:       case 'overload': g.confirmOverload(); break;
387:       default: break;
388:     }
389:   }
