391:   setTab(tab) {
392:     const app = $('app');
393:     app.dataset.tab = tab;
394:     document.querySelectorAll('.tab').forEach((el) => el.classList.toggle('active', el.dataset.tab === tab));
395:     // let the browser apply display before measuring canvas rects
396:     requestAnimationFrame(() => {
397:       this.game.mineRenderer?.resize();
398:       this.game.combatRenderer?.resize();
399:     });
400:   }
