413:   renderResources() {
414:     const s = this.s;
415:     const showShards = s.shards > 0;
416:     setText(this.refs.topLevel, String(s.level || 1));
417:     const hasPoints = (s.points || 0) > 0 || (s.perkPoints || 0) > 0;
418:     this.refs.topPoints.hidden = !hasPoints;
419:     for (const key of ORE_ORDER) {
420:       const ref = this.resEls[key];
421:       const unlocked = LAYERS.findIndex((l) => l.ore === key) < s.layersUnlocked;
422:       const visible = unlocked || (s.ores[key] || 0) > 0;
423:       ref.chip.style.display = visible ? '' : 'none';
424:       ref.chip.classList.toggle('locked', !unlocked);
425:       setText(ref.val, fmt(s.ores[key] || 0));
426:       const layerIndex = LAYERS.findIndex((l) => l.ore === key);
427:       const rate = layerIndex >= 0 ? (s.drills[layerIndex] || 0) * drillRate(s, layerIndex) : 0;
428:       setText(ref.per, rate > 0 ? `+${fmtRate(rate)}` : '');
429:       ref.chip.title = `${ORES[key].name}${rate > 0 ? ` · ${fmtRate(rate)}` : ''}`;
430:     }
431:     const caps = this.resEls.caps;
432:     const capsRate = salvageCapsRate(s);
433:     setText(caps.val, fmt(s.caps));
434:     setText(caps.per, capsRate > 0 ? `+${fmtRate(capsRate)}` : '');
435:     caps.chip.title = `Salvage caps (money) · ${capsRate > 0 ? `${fmtRate(capsRate)} from salvage · ` : ''}earned in combat, spent on upgrades and outfits. ${fmt(s.stats.totalCaps || 0)} lifetime.`;
436:     const shards = this.resEls.shards;
437:     shards.chip.style.display = showShards ? '' : 'none';
438:     setText(shards.val, fmt(s.shards));
439:     shards.chip.title = `Core shards · +${Math.round(s.shards * 10)}% ore, +${Math.round(s.shards * 8)}% damage`;
440:   }
