442:   renderMine() {
443:     const s = this.s;
444:     const r = this.refs;
445:     const layer = LAYERS[s.layer] || LAYERS[0];
446:     const node = s.nodes[s.layer] || 0;
447:     const maxHp = layerMaxHp(s, s.layer);
448:     const hp = Math.min(maxHp, s.veinHp[s.layer] ?? maxHp);
449:     setText(r.layerBadge, `${layer.short} // ${layer.depth}M`);
450:     setText(r.veinLabel, `VEIN ${String(node + 1).padStart(2, '0')}`);
451:     setText(r.richnessLabel, `RICH ×${nodeRichness(node).toFixed(2)}`);
452:     setText(r.veinHpText, `${Math.ceil(hp)} / ${maxHp}`);
453:     r.veinBar.style.width = `${Math.max(0, Math.min(100, (hp / maxHp) * 100))}%`;
454:     setText(r.strikeSub, `+${fmt(strikeYield(s, s.layer), 1)} ${ORES[layer.ore].name.toUpperCase()} PER HIT`);
455:     setText(r.pickPower, fmt(pickPower(s), 1));
456:     const totalRate = LAYERS.reduce((sum, _, i) => sum + (s.drills[i] || 0) * drillRate(s, i), 0);
457:     setText(r.autoYield, fmtRate(totalRate));
458:     setText(r.depthText, `${layer.name.toUpperCase()} // ${layer.depth}M`);
459:     r.sceneTip.classList.toggle('hidden', (s.stats.clicks || 0) > 3);
460:     setText(r.objectiveText, this.objectiveText());
461:     const autoMine = !!s.autoMine;
462:     r.autoMineBtn.classList.toggle('on', autoMine);
463:     r.autoMineBtn.setAttribute('aria-pressed', String(autoMine));
464:     setText(r.autoMineLabel, autoMine ? 'AUTO-MINE: ON' : 'AUTO-MINE: OFF');
465: 
466:     this.layerEls.forEach(({ btn, req }, i) => {
467:       const l = LAYERS[i];
468:       btn.classList.toggle('active', i === s.layer);
469:       const unlocked = i < s.layersUnlocked;
470:       btn.classList.toggle('locked', !unlocked);
471:       const unlock = l.unlock;
472:       let ready = false;
473:       if (!unlocked && unlock) {
474:         ready = s.pickaxe >= unlock.pickaxe && canAffordOre(s, unlock.ore);
475:       }
476:       btn.classList.toggle('ready', ready);
477:       if (unlocked) {
478:         const rate = (s.drills[i] || 0) * drillRate(s, i);
479:         setText(req, `${l.baseYield}/hit${rate > 0 ? ` · +${fmtRate(rate)}` : ''}`);
480:       } else if (ready) {
481:         setText(req, `UNLOCK · ${costLabel(unlock.ore)}`);
482:       } else {
483:         setText(req, `PK.${unlock.pickaxe} · ${costLabel(unlock.ore)}`);
484:       }
485:     });
486:   }
