488:   renderForge() {
489:     const s = this.s;
490:     const r = this.refs;
491:     const p = playerStats(s);
492: 
493:     // ── survivor level / attributes / perks ──────────────────
494:     const need = xpNeeded(s.level || 1);
495:     setText(r.forgeLevel, String(s.level || 1));
496:     r.levelXpBar.style.width = `${Math.max(0, Math.min(100, ((s.xp || 0) / need) * 100))}%`;
497:     setText(r.levelXpText, `${fmt(s.xp || 0, 0)} / ${fmt(need)} XP`);
498:     setText(r.levelBonus, `+${Math.round((levelHpMult(s) - 1) * 100)}% HP · +${Math.round((levelAtkMult(s) - 1) * 100)}% ATK`);
499:     const unspent = s.points || 0;
500:     setText(r.levelPoints, `${unspent} POINT${unspent === 1 ? '' : 'S'}`);
501:     r.levelPoints.classList.toggle('ready', unspent > 0);
502:     setText(r.perkBadge, String(s.perkPoints || 0));
503:     r.perkBtn.classList.toggle('ready', (s.perkPoints || 0) > 0);
504: 
505:     for (const attr of ATTRIBUTES) {
506:       const els = this.attrEls[attr.id];
507:       const val = attrLevel(s, attr.id);
508:       setText(els.val, String(val));
509:       setText(els.eff, attr.effect(val));
510:       els.plus.disabled = unspent < 1;
511:       els.plus.title = unspent < 1 ? 'No attribute points available' : `Add 1 ${attr.name}`;
512:     }
513:     const totalSpent = ATTRIBUTES.reduce((sum, a) => sum + attrLevel(s, a.id), 0);
514:     const owned = PERKS.filter((perk) => perkRank(s, perk.id) > 0)
515:       .map((perk) => `${perk.name} ×${perkRank(s, perk.id)}`);
516:     if ((s.perkPoints || 0) > 0) setText(r.perkLineText, `${s.perkPoints} perk choice${s.perkPoints > 1 ? 's' : ''} ready — open PERKS.`);
517:     else if (owned.length) setText(r.perkLineText, owned.join(' · '));
518:     else setText(r.perkLineText, 'No perks yet — earn one every 3 levels.');
519:     r.respecBtn.disabled = totalSpent === 0;
520: 
521:     // pickaxe
522:     const pc = pickaxeCost(s.pickaxe);
523:     const pcAff = canAfford(s, pc);
524:     const pick = this.cardEls.pickaxe;
525:     pick.lvl.textContent = `LV.${s.pickaxe}`;
526:     pick.desc.innerHTML = `All tools <b>${fmt(pickPower(s), 1)}</b> → <b>${fmt((2 + 2.3 * s.pickaxe) * miningTool(s).powerMult, 1)}</b> vein power · raises every seam`;
527:     pick.cost.textContent = costLabel(pc);
528:     pick.card.classList.toggle('affordable', pcAff);
529:     setCta(pick.cta, 'UPGRADE', 'upgrade');
530: 
531:     // crew
532:     const cc = crewCost(s.crew);
533:     const ccAff = canAfford(s, cc);
534:     const crew = this.cardEls.crew;
535:     crew.lvl.textContent = `LV.${s.crew}`;
536:     crew.desc.innerHTML = `Ore yield <b>+${s.crew * 8}%</b> → <b>+${(s.crew + 1) * 8}%</b> · survivors work the rigs`;
537:     crew.cost.textContent = costLabel(cc);
538:     crew.card.classList.toggle('affordable', ccAff);
539:     setCta(crew.cta, 'RECRUIT', 'upgrade');
540:     setText(r.crewBadge, `CREW ${s.crew}`);
541:     const oreRate = LAYERS.reduce((sum, _, i) => sum + (s.drills[i] || 0) * drillRate(s, i), 0);
542:     const capsRate = salvageCapsRate(s);
543:     setText(r.drillRateTotal, `${fmtRate(oreRate)} ore · ${fmtRate(capsRate)} caps`);
544: 
545:     // mining tools
546:     const equippedTool = miningTool(s);
547:     const toolsReady = MINING_TOOLS.filter((tool) => s.tools?.[tool.id]).length;
548:     setText(r.toolSummary, `${toolsReady} / ${MINING_TOOLS.length} READY · ${equippedTool.name.toUpperCase()}`);
549:     for (const tool of MINING_TOOLS) {
550:       const els = this.toolCardEls[tool.id];
551:       const unlocked = !!s.tools?.[tool.id];
552:       const equipped = s.equippedTool === tool.id;
553:       els.desc.textContent = tool.stats;
554:       els.card.classList.toggle('equipped', equipped);
555:       els.card.classList.toggle('locked', !unlocked);
556:       els.card.classList.toggle('affordable', !unlocked && canAfford(s, tool.unlock || {}));
557:       if (equipped) {
558:         els.cost.textContent = 'EQUIPPED';
559:         setCta(els.cta, 'IN USE', 'inuse');
560:       } else if (unlocked) {
561:         els.cost.textContent = 'SCHEMATIC OWNED';
562:         setCta(els.cta, 'EQUIP', 'equip');
563:       } else {
564:         els.cost.textContent = costLabel(tool.unlock || {});
565:         setCta(els.cta, 'UNLOCK', 'unlock');
566:       }
567:     }
568: 
569:     // combat weapons
570:     const equippedWeapon = combatWeapon(s);
571:     const weaponsReady = COMBAT_WEAPONS.filter((weapon) => s.weapons?.[weapon.id]).length;
572:     setText(r.weaponSummary, `${weaponsReady} / ${COMBAT_WEAPONS.length} READY · ${equippedWeapon.name.toUpperCase()}`);
573:     for (const weapon of COMBAT_WEAPONS) {
574:       const els = this.weaponCardEls[weapon.id];
575:       const unlocked = !!s.weapons?.[weapon.id];
576:       const equipped = s.equippedWeapon === weapon.id;
577:       const swing = Math.max(220, Math.round((750 * weapon.speedMult) / (p.speedMult || 1)));
578:       const crit = Math.max(0, p.crit - equippedWeapon.critBonus + weapon.critBonus);
579:       els.desc.textContent = `DMG ×${weapon.damageMult.toFixed(2)} · ${(swing / 1000).toFixed(2)}s swing · ${Math.round(crit * 100)}% crit`;
580:       els.card.classList.toggle('equipped', equipped);
581:       els.card.classList.toggle('locked', !unlocked);
582:       els.card.classList.toggle('affordable', !unlocked && canAfford(s, weapon.unlock || {}));
583:       if (equipped) {
584:         els.cost.textContent = 'EQUIPPED';
585:         setCta(els.cta, 'IN USE', 'inuse');
586:       } else if (unlocked) {
587:         els.cost.textContent = 'SCHEMATIC OWNED';
588:         setCta(els.cta, 'EQUIP', 'equip');
589:       } else {
590:         els.cost.textContent = costLabel(weapon.unlock || {});
591:         setCta(els.cta, 'UNLOCK', 'unlock');
592:       }
593:     }
594: 
595:     // gear
596:     const wc = weaponCost(s.combat.gear.weapon);
597:     const wAff = canAfford(s, wc);
598:     const weapon = this.cardEls.weapon;
599:     weapon.lvl.textContent = `LV.${s.combat.gear.weapon}`;
600:     weapon.desc.innerHTML = `All weapons · Damage <b>${fmt(p.attack, 1)}</b> · ${Math.round(p.crit * 100)}% crit · ${(playerAttackInterval(s) / 1000).toFixed(2)}s swing`;
601:     weapon.cost.textContent = costLabel(wc);
602:     weapon.card.classList.toggle('affordable', wAff);
603:     setCta(weapon.cta, 'FORGE', 'upgrade');
604: 
605:     const ac = armorCost(s.combat.gear.armor);
606:     const aAff = canAfford(s, ac);
607:     const armor = this.cardEls.armor;
608:     const nextArmor = playerStats({
609:       ...s,
610:       combat: { ...s.combat, gear: { ...s.combat.gear, armor: s.combat.gear.armor + 1 } },
611:     });
612:     armor.lvl.textContent = `LV.${s.combat.gear.armor}`;
613:     armor.desc.innerHTML = `HP <b>${fmt(p.maxHp)}</b> → <b>${fmt(nextArmor.maxHp)}</b> · ${Math.round(p.defense * 100)}% damage resist`;
614:     armor.cost.textContent = costLabel(ac);
615:     armor.card.classList.toggle('affordable', aAff);
616:     setCta(armor.cta, 'FORGE', 'upgrade');
617: 
618:     const stimMax = s.combat.gear.stim >= STIM_MAX;
619:     const stim = this.cardEls.stim;
620:     stim.lvl.textContent = `LV.${s.combat.gear.stim}`;
621:     if (stimMax) {
622:       stim.desc.innerHTML = `Heals <b>${p.healPerKill}</b> HP per kill · knockout ${p.deathMs / 1000}s`;
623:       stim.cost.textContent = 'Max tier reached';
624:       stim.card.classList.remove('affordable');
625:       stim.card.classList.add('maxed');
626:       setCta(stim.cta, 'MAX', 'inuse');
627:     } else {
628:       const sc = stimCost(s.combat.gear.stim);
629:       const sAff = canAfford(s, sc);
630:       stim.desc.innerHTML = `Heals <b>${p.healPerKill}</b> → <b>${8 + 5 * (s.combat.gear.stim + 1)}</b> HP per kill · faster reboot`;
631:       stim.cost.textContent = costLabel(sc);
632:       stim.card.classList.toggle('affordable', sAff);
633:       stim.card.classList.remove('maxed');
634:       setCta(stim.cta, 'BUILD', 'upgrade');
635:     }
636: 
637:     // drills
638:     this.drillEls.forEach(({ btn, name, sub, cost, buy }, i) => {
639:       const unlocked = i < s.layersUnlocked;
640:       const l = LAYERS[i];
641:       const count = s.drills[i] || 0;
642:       btn.classList.toggle('locked', !unlocked);
643:       name.firstChild.textContent = `${ORES[l.ore].name} Drill`;
644:       if (!unlocked) {
645:         sub.textContent = 'Layer not yet opened';
646:         cost.textContent = 'LOCKED';
647:         buy.classList.remove('show');
648:         btn.classList.remove('affordable');
649:       } else {
650:         const per = drillRate(s, i);
651:         sub.textContent = `×${count} · ${fmtRate(per)} each · ${fmtRate(per * count)} total`;
652:         const dc = drillCost(i, count);
653:         cost.textContent = costLabel(dc);
654:         btn.classList.toggle('affordable', canAfford(s, dc));
655:       }
656:       cost.closest('.drill-buy').querySelector('b').textContent = 'BUY';
657:     });
658: 
659:     // outfits
660:     let crafted = 0;
661:     this.outfitEls.forEach((els, i) => {
662:       const outfit = OUTFITS[i];
663:       const lvl = outfitLevel(s, outfit.id);
664:       if (lvl > 0) crafted += 1;
665:       const maxed = lvl >= outfit.max;
666:       setText(els.lvl, `${lvl}/${outfit.max}`);
667:       setText(els.desc, `${outfit.slot} · ${maxed ? outfit.effect(lvl) : `Next: ${outfit.effect(lvl + 1)}`}`);
668:       els.card.title = outfit.blurb;
669:       if (maxed) {
670:         setText(els.cost, 'Max tier reached');
671:         setCta(els.cta, 'MAX', 'inuse');
672:         els.card.classList.remove('affordable');
673:         els.card.classList.add('maxed');
674:       } else {
675:         const cost = outfitCost(outfit, lvl);
676:         const aff = canAfford(s, cost);
677:         setText(els.cost, costLabel(cost));
678:         setCta(els.cta, lvl > 0 ? 'UPGRADE' : 'CRAFT', 'upgrade');
679:         els.card.classList.toggle('affordable', aff);
680:         els.card.classList.remove('maxed');
681:       }
682:     });
683:     setText(r.outfitSummary, `${crafted} / ${OUTFITS.length} CRAFTED`);
684: 
685:     // core
686:     const gain = overloadGain(s);
687:     r.overloadBtn.disabled = s.combat.primeKills < 1;
688:     if (s.combat.primeKills < 1) {
689:       r.coreDesc.textContent = 'Defeat Warden Prime in The Black Vault to charge the core. Overloading resets your run for permanent shards.';
690:       r.coreDesc.classList.remove('ready');
691:     } else {
692:       r.coreDesc.textContent = `Core charged by ${s.combat.primeKills} Prime kill${s.combat.primeKills > 1 ? 's' : ''}. Overload yields ${gain} core shard${gain > 1 ? 's' : ''} and resets ore, rigs, and territory.`;
693:       r.coreDesc.classList.add('ready');
694:     }
695:   }
