704:   renderLoadout() {
705:     const s = this.s;
706:     const r = this.refs;
707:     const score = this.loadoutScore();
708:     setText(r.gearScore, `GEAR ${score}`);
709:     setText(r.packSummary, `${(s.inventory || []).length} / ${MAX_INVENTORY} · GEAR ${score}`);
710:     const cost = lootRunCost(s);
711:     setText(r.salvageCost, fmt(cost));
712:     r.salvageRunBtn?.classList.toggle('affordable', canAfford(s, { caps: cost }));
713:     if (!this.loadoutEls) return;
714:     for (const slot of GEAR_SLOTS) {
715:       const els = this.loadoutEls[slot.id];
716:       if (!els) continue;
717:       const item = equippedItem(s, slot.id);
718:       els.btn.classList.toggle('filled', !!item);
719:       if (item) {
720:         const rarity = rarityOf(item);
721:         els.btn.style.setProperty('--rarity', rarity.color);
722:         els.name.textContent = item.name.toUpperCase();
723:         els.rarity.textContent = rarity.name.toUpperCase();
724:         els.btn.title = `${item.name} · ${rarity.name} · ${gearStatLines(item).join(' · ')}`;
725:       } else {
726:         els.btn.style.removeProperty('--rarity');
727:         els.name.textContent = 'EMPTY';
728:         els.rarity.textContent = '';
729:         els.btn.title = `No ${slot.name.toLowerCase()} fitted. Open loadout.`;
730:       }
