187:   veinBreak() {
188:     this.veinHidden = 0.22;
189:     this.flash = 1;
190:     this.shake = 9;
191:     this.nodePulse = 1;
192:     for (let i = 0; i < 26; i++) {
193:       const a = Math.random() * TAU;
194:       const sp = 30 + Math.random() * 130;
195:       this.particles.push({
196:         x: this.veinX, y: this.veinY,
197:         vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 30,
198:         life: 0.5 + Math.random() * 0.7, max: 1.2,
199:         size: 1 + Math.random() * 3.2, color: this.currentLayer().glow,
200:         gravity: 230,
201:       });
202:     }
203:     this.floats.push({
204:       x: this.veinX, y: this.veinY - 40, vy: -22, life: 1.5, max: 1.5,
205:       text: 'VEIN SHATTERED', color: '#ffe3bc', size: 10,
206:     });
207:   }
