209:   addDustBurst(x, y, count = 8, color = '#c9b18d') {
210:     for (let i = 0; i < count; i++) {
211:       const a = -Math.PI / 2 + (Math.random() - 0.5) * 2.4;
212:       const sp = 18 + Math.random() * 60;
213:       this.particles.push({
214:         x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
215:         life: 0.3 + Math.random() * 0.4, max: 0.7, size: 1 + Math.random() * 2.2,
216:         color, gravity: 120,
217:       });
218:     }
219:   }
