221:   draw(dt, t) {
222:     const ctx = this.ctx;
223:     const state = this.game.state;
224:     const layerIndex = state.layer || 0;
225:     const layer = LAYERS[layerIndex] || LAYERS[0];
226:     const node = state.nodes?.[layerIndex] || 0;
227:     const key = `${layerIndex}:${node}`;
228:     if (key !== this.lastKey) {
229:       this.regenerateVein();
230:       this.nodePulse = 1;
231:     }
232:     if (this.lastLayer !== layerIndex) {
233:       this.lastLayer = layerIndex;
234:       this.bgSeed = 3 + layerIndex * 17;
235:       this.regenerateVein();
236:     }
237: 
238:     this.shake = Math.max(0, this.shake - dt * 28);
239:     this.flash = Math.max(0, this.flash - dt * 3.4);
240:     this.veinHidden = Math.max(0, this.veinHidden - dt);
241:     this.nodePulse = Math.max(0, this.nodePulse - dt * 2.2);
242: 
243:     if (this.swing < 1) {
244:       this.swing = Math.min(1, this.swing + dt / 0.34);
245:       if (!this.impacted && this.swing >= 0.42) {
246:         this.impacted = true;
247:         this.shake = Math.max(this.shake, 5);
248:         const px = this.veinX - 6 * this.scale;
249:         const py = this.veinY + 2;
250:         this.addDustBurst(px, py, 12, layer.glow);
251:         for (let i = 0; i < 5; i++) {
252:           this.particles.push({
253:             x: px, y: py,
254:             vx: -40 - Math.random() * 70, vy: -40 - Math.random() * 90,
255:             life: 0.25 + Math.random() * 0.3, max: 0.55,
256:             size: 0.8 + Math.random() * 1.8, color: '#ffd9a5', gravity: 300,
257:           });
258:         }
259:       }
260:     }
261: 
262:     ctx.save();
263:     if (this.shake > 0.2) {
264:       ctx.translate((Math.random() - 0.5) * this.shake, (Math.random() - 0.5) * this.shake);
265:     }
266: 
267:     this.drawBackground(ctx, t, layer, layerIndex);
268:     this.drawDust(ctx, t);
269:     this.drawCart(ctx, t, layer);
270:     this.drawDrillRig(ctx, t, layer, index0(state, layerIndex));
271:     this.drawCritter(ctx, t);
272:     this.drawVein(ctx, t, layer, state, layerIndex, node, key);
273:     this.drawMiner(ctx, t, layer);
274: 
275:     ctx.restore();
276: 
277:     this.updateParticles(dt);
278:     this.drawParticles(ctx);
279:     this.drawFloats(dt, ctx);
280: 
281:     // hit flash
282:     if (this.flash > 0.02) {
283:       const g = ctx.createRadialGradient(this.veinX, this.veinY, 4, this.veinX, this.veinY, this.w * 0.5);
284:       g.addColorStop(0, rgba(layer.glow, 0.28 * this.flash));
285:       g.addColorStop(1, 'rgba(0,0,0,0)');
286:       ctx.fillStyle = g;
287:       ctx.fillRect(0, 0, this.w, this.h);
288:     }
289: 
290:     // vignette
291:     const v = ctx.createRadialGradient(this.w / 2, this.h / 2, this.h * 0.2, this.w / 2, this.h / 2, this.h * 0.85);
292:     v.addColorStop(0, 'rgba(0,0,0,0)');
293:     v.addColorStop(1, 'rgba(0,0,0,0.55)');
294:     ctx.fillStyle = v;
295:     ctx.fillRect(0, 0, this.w, this.h);
296:   }
297: 
298:   drawBackground(ctx, t, layer, layerIndex) {
299:     const { w, h, floorY } = this;
300:     const cave = layer.cave;
301:     const glow = layer.glow;
302:     const g = ctx.createLinearGradient(0, 0, 0, h);
303:     g.addColorStop(0, '#070806');
304:     g.addColorStop(0.35, cave);
305:     g.addColorStop(1, '#060706');
306:     ctx.fillStyle = g;
307:     ctx.fillRect(0, 0, w, h);
308: 
309:     // warm glow around vein
310:     const vg = ctx.createRadialGradient(this.veinX, this.veinY, 2, this.veinX, this.veinY, Math.max(90, w * 0.35));
311:     vg.addColorStop(0, rgba(glow, 0.16));
312:     vg.addColorStop(0.5, rgba(glow, 0.045));
313:     vg.addColorStop(1, 'rgba(0,0,0,0)');
314:     ctx.fillStyle = vg;
315:     ctx.fillRect(0, 0, w, h);
316: 
317:     const rnd = mulberry32(this.bgSeed);
318: 
319:     // rock plates on walls
320:     for (let i = 0; i < 16; i++) {
321:       const x = rnd() * w;
322:       const y = rnd() * h * 0.65;
323:       const rw = 26 + rnd() * 90;
324:       const rh = 16 + rnd() * 55;
325:       ctx.beginPath();
326:       ctx.moveTo(x - rw / 2, y + rh / 2);
327:       ctx.lineTo(x - rw * 0.3, y - rh / 2);
328:       ctx.lineTo(x + rw * 0.35, y - rh * 0.42);
329:       ctx.lineTo(x + rw / 2, y + rh * 0.3);
330:       ctx.closePath();
331:       ctx.fillStyle = `rgba(0,0,0,${0.08 + rnd() * 0.14})`;
332:       ctx.fill();
333:       ctx.strokeStyle = 'rgba(255,255,255,0.025)';
334:       ctx.lineWidth = 1;
335:       ctx.stroke();
336:     }
337: 
338:     // tunnel arch in back
339:     ctx.save();
340:     ctx.beginPath();
341:     ctx.ellipse(w * 0.42, floorY - 30, w * 0.23, h * 0.36, 0, Math.PI, 0);
342:     ctx.lineTo(w * 0.65, floorY - 8);
343:     ctx.lineTo(w * 0.19, floorY - 8);
344:     ctx.closePath();
345:     const tg = ctx.createLinearGradient(0, floorY - h * 0.5, 0, floorY);
346:     tg.addColorStop(0, '#020302');
347:     tg.addColorStop(1, '#080907');
348:     ctx.fillStyle = tg;
349:     ctx.fill();
350:     ctx.strokeStyle = 'rgba(255,255,255,0.035)';
351:     ctx.stroke();
352:     ctx.restore();
353: 
354:     // wooden support beams
355:     this.drawBeam(ctx, w * 0.12, floorY, h * 0.56, 9 * this.scale, layerIndex);
356:     this.drawBeam(ctx, w * 0.37, floorY, h * 0.44, 7 * this.scale, layerIndex);
357: 
358:     // crossbeam
359:     ctx.save();
360:     ctx.strokeStyle = '#1b1710';
361:     ctx.lineWidth = 9 * this.scale;
362:     ctx.lineCap = 'round';
363:     ctx.beginPath();
364:     ctx.moveTo(w * 0.08, h * 0.12);
365:     ctx.lineTo(w * 0.44, h * 0.09);
366:     ctx.stroke();
367:     ctx.strokeStyle = 'rgba(255,214,160,0.08)';
368:     ctx.lineWidth = 2;
369:     ctx.stroke();
370:     ctx.restore();
371: 
372:     // stalactites
373:     const rnd2 = mulberry32(this.bgSeed + 9);
374:     ctx.fillStyle = '#070806';
375:     for (let i = 0; i < 12; i++) {
376:       const x = rnd2() * w;
377:       const len = 10 + rnd2() * 34;
378:       const wid = 4 + rnd2() * 10;
379:       ctx.beginPath();
380:       ctx.moveTo(x - wid, 0);
381:       ctx.lineTo(x + wid, 0);
382:       ctx.lineTo(x + wid * 0.15, len);
383:       ctx.closePath();
384:       ctx.fill();
385:     }
386: 
387:     // rails and floor
388:     const fg = ctx.createLinearGradient(0, floorY - 20, 0, h);
389:     fg.addColorStop(0, '#1a1711');
390:     fg.addColorStop(1, '#070806');
391:     ctx.fillStyle = fg;
392:     ctx.beginPath();
393:     ctx.moveTo(0, floorY + 2);
394:     for (let x = 0; x <= w; x += 24) {
395:       ctx.lineTo(x, floorY + 2 + Math.sin(x * 0.09) * 2.5);
396:     }
397:     ctx.lineTo(w, h);
398:     ctx.lineTo(0, h);
399:     ctx.closePath();
400:     ctx.fill();
401: 
402:     // rail
403:     ctx.save();
404:     ctx.strokeStyle = '#2b2a25';
405:     ctx.lineWidth = 2;
406:     ctx.beginPath();
407:     ctx.moveTo(0, floorY + 15);
408:     ctx.lineTo(w, floorY + 17);
409:     ctx.stroke();
410:     ctx.strokeStyle = 'rgba(255,255,255,0.06)';
411:     ctx.lineWidth = 1;
412:     ctx.beginPath();
413:     ctx.moveTo(0, floorY + 13);
414:     ctx.lineTo(w, floorY + 15);
415:     ctx.stroke();
416:     // sleepers
417:     ctx.strokeStyle = '#18160f';
418:     ctx.lineWidth = 5;
419:     for (let x = 8; x < w; x += 30) {
420:       ctx.beginPath();
421:       ctx.moveTo(x, floorY + 10);
422:       ctx.lineTo(x + 5, floorY + 21);
423:       ctx.stroke();
424:     }
425:     ctx.restore();
426: 
427:     // foreground rubble
428:     const rnd3 = mulberry32(this.bgSeed + 33);
429:     for (let i = 0; i < 10; i++) {
430:       const x = rnd3() * w;
431:       const y = floorY + 12 + rnd3() * (h - floorY - 14);
432:       const rw = 8 + rnd3() * 26;
433:       ctx.beginPath();
434:       ctx.ellipse(x, y, rw, rw * 0.35, rnd3(), 0, TAU);
435:       ctx.fillStyle = `rgba(0,0,0,${0.3 + rnd3() * 0.35})`;
436:       ctx.fill();
437:     }
438: 
439:     // hanging lamp
440:     const lampX = w * 0.28;
441:     const lampY = h * 0.22 + Math.sin(t * 1.4) * 2;
442:     ctx.save();
443:     ctx.strokeStyle = '#1c1a15';
444:     ctx.lineWidth = 1.5;
445:     ctx.beginPath();
446:     ctx.moveTo(lampX, 0);
447:     ctx.lineTo(lampX, lampY - 6);
448:     ctx.stroke();
449:     const flicker = 0.75 + Math.sin(t * 13.1) * 0.08 + Math.sin(t * 27.3) * 0.05;
450:     const lg = ctx.createRadialGradient(lampX, lampY, 1, lampX, lampY, Math.min(110, w * 0.28));
451:     lg.addColorStop(0, `rgba(255,180,90,${0.22 * flicker})`);
452:     lg.addColorStop(1, 'rgba(255,150,60,0)');
453:     ctx.fillStyle = lg;
454:     ctx.fillRect(0, 0, w, h);
455:     ctx.fillStyle = '#ffc47a';
456:     ctx.beginPath();
457:     ctx.arc(lampX, lampY, 2.6, 0, TAU);
458:     ctx.fill();
459:     ctx.restore();
460:   }
461: 
462:   drawBeam(ctx, x, floorY, topY, width, idx) {
463:     ctx.save();
464:     ctx.fillStyle = '#17130d';
465:     ctx.beginPath();
466:     ctx.moveTo(x - width / 2, 0);
467:     ctx.lineTo(x + width / 2, 0);
468:     ctx.lineTo(x + width * 0.4, floorY);
469:     ctx.lineTo(x - width * 0.55, floorY);
470:     ctx.closePath();
471:     ctx.fill();
472:     ctx.strokeStyle = 'rgba(255,210,150,0.055)';
473:     ctx.lineWidth = 1;
474:     ctx.stroke();
475:     // nails
476:     ctx.fillStyle = 'rgba(255,210,150,0.12)';
477:     for (let y = 14; y < floorY; y += 40) {
478:       ctx.fillRect(x - width * 0.2, y, 2, 2);
479:       ctx.fillRect(x + width * 0.14, y + 18, 2, 2);
480:     }
481:     ctx.restore();
482:   }
483: 
484:   drawDust(ctx, t) {
485:     for (const d of this.dust) {
486:       const x = (d.x * this.w + Math.sin(t * 0.3 + d.ph) * 14 + t * d.drift * 5) % this.w;
487:       const y = (d.y * this.h - ((t * d.spd * 30) % (this.h * 0.5)) + this.h) % this.h;
488:       ctx.fillStyle = `rgba(255,222,170,${d.a * (0.5 + 0.5 * Math.sin(t + d.ph))})`;
489:       ctx.beginPath();
490:       ctx.arc(x, y, d.r, 0, TAU);
491:       ctx.fill();
492:     }
493:   }
494: 
495:   drawCart(ctx, t, layer) {
496:     const x = ((t * 6) % (this.w + 140)) - 70;
497:     const y = this.floorY + 4;
498:     const s = this.scale * 0.75;
499:     ctx.save();
500:     ctx.globalAlpha = 0.42;
501:     ctx.translate(x, y);
502:     ctx.scale(s, s);
503:     // cart body
504:     ctx.fillStyle = '#15140f';
505:     ctx.beginPath();
506:     ctx.moveTo(-22, -20); ctx.lineTo(22, -20); ctx.lineTo(17, 0); ctx.lineTo(-17, 0); ctx.closePath();
507:     ctx.fill();
508:     ctx.strokeStyle = 'rgba(255,210,150,0.09)';
509:     ctx.stroke();
510:     // ore lumps
511:     ctx.fillStyle = rgba(layer.glow, 0.55);
512:     ctx.beginPath(); ctx.arc(-8, -23, 6, 0, TAU); ctx.arc(3, -26, 7, 0, TAU); ctx.arc(13, -22, 5, 0, TAU); ctx.fill();
513:     // wheels
514:     ctx.fillStyle = '#0d0e0a';
515:     ctx.beginPath(); ctx.arc(-12, 3, 7, 0, TAU); ctx.arc(12, 3, 7, 0, TAU); ctx.fill();
516:     ctx.strokeStyle = 'rgba(255,255,255,0.12)';
517:     ctx.lineWidth = 1.2;
518:     for (const wx of [-12, 12]) {
519:       ctx.beginPath(); ctx.arc(wx, 3, 7, 0, TAU); ctx.stroke();
520:       ctx.beginPath();
521:       const a = t * 2.5;
522:       ctx.moveTo(wx + Math.cos(a) * 5, 3 + Math.sin(a) * 5);
523:       ctx.lineTo(wx - Math.cos(a) * 5, 3 - Math.sin(a) * 5);
524:       ctx.stroke();
525:     }
526:     ctx.restore();
527:   }
528: 
529:   drawDrillRig(ctx, t, layer, drills) {
530:     if (!drills || drills <= 0) return;
531:     const x = this.w * 0.155;
532:     const y = this.floorY + 3;
533:     const s = this.scale * 0.84;
534:     const speed = 2.4 + Math.min(4, drills * 0.16);
535:     const piston = (Math.sin(t * speed) + 1) / 2;
536:     ctx.save();
537:     ctx.translate(x, y);
538:     ctx.scale(s, s);
539: 
540:     // shadow
541:     ctx.fillStyle = 'rgba(0,0,0,0.45)';
542:     ctx.beginPath(); ctx.ellipse(0, 0, 38, 7, 0, 0, TAU); ctx.fill();
543: 
544:     // ore pile
545:     ctx.fillStyle = rgba(layer.glow, 0.35);
546:     for (let i = 0; i < 5; i++) {
547:       ctx.beginPath();
548:       ctx.arc(-30 + i * 9, -4 - (i % 2) * 3, 4 + (i % 3), 0, TAU);
549:       ctx.fill();
550:     }
551: 
552:     // base
553:     ctx.fillStyle = '#1b1d17';
554:     ctx.fillRect(-26, -14, 52, 13);
555:     ctx.fillStyle = '#2a2c24';
556:     ctx.fillRect(-26, -16, 52, 4);
557:     ctx.strokeStyle = 'rgba(255,255,255,0.07)';
558:     ctx.strokeRect(-26, -14, 52, 13);
559: 
560:     // mast
561:     ctx.strokeStyle = '#31352b';
562:     ctx.lineWidth = 5;
563:     ctx.beginPath();
564:     ctx.moveTo(-14, -16); ctx.lineTo(-7, -64);
565:     ctx.moveTo(14, -16); ctx.lineTo(7, -64);
566:     ctx.stroke();
567:     ctx.lineWidth = 2;
568:     ctx.strokeStyle = '#454a3b';
569:     ctx.beginPath();
570:     ctx.moveTo(-19, -30); ctx.lineTo(17, -44);
571:     ctx.moveTo(-18, -44); ctx.lineTo(16, -30);
572:     ctx.stroke();
573: 
574:     // piston
575:     const py = -30 - piston * 26;
576:     ctx.strokeStyle = '#5c6250';
577:     ctx.lineWidth = 4;
578:     ctx.beginPath(); ctx.moveTo(0, -62); ctx.lineTo(0, py); ctx.stroke();
579:     ctx.fillStyle = '#363b2f';
580:     ctx.fillRect(-9, py, 18, 11);
581:     ctx.fillStyle = '#1c1f18';
582:     ctx.fillRect(-11, py + 8, 22, 4);
583: 
584:     // spinning flywheel
585:     ctx.save();
586:     ctx.translate(17, -24);
587:     ctx.rotate(t * speed * 0.9);
588:     ctx.strokeStyle = '#4a5040';
589:     ctx.lineWidth = 2;
590:     ctx.beginPath(); ctx.arc(0, 0, 7, 0, TAU); ctx.stroke();
591:     for (let i = 0; i < 3; i++) {
592:       const a = i * TAU / 3;
593:       ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(Math.cos(a) * 6, Math.sin(a) * 6); ctx.stroke();
594:     }
595:     ctx.restore();
596: 
597:     // lamp
598:     const blink = Math.sin(t * (3 + drills * 0.2)) > 0.65;
599:     ctx.fillStyle = blink ? '#ffb15c' : '#5a3a1e';
600:     ctx.beginPath(); ctx.arc(0, -68, 2.5, 0, TAU); ctx.fill();
601:     if (blink) {
602:       const lg = ctx.createRadialGradient(0, -68, 0, 0, -68, 18);
603:       lg.addColorStop(0, 'rgba(255,177,92,0.25)');
604:       lg.addColorStop(1, 'rgba(255,177,92,0)');
605:       ctx.fillStyle = lg; ctx.fillRect(-20, -88, 40, 40);
606:     }
607: 
608:     // exhaust puffs
609:     for (let i = 0; i < 3; i++) {
610:       const ph = (t * 0.5 + i * 0.33) % 1;
611:       ctx.fillStyle = `rgba(170,170,150,${0.14 * (1 - ph)})`;
612:       ctx.beginPath();
613:       ctx.arc(-8 - ph * 14, -20 - ph * 30, 3 + ph * 7, 0, TAU);
614:       ctx.fill();
615:     }
616: 
617:     // count
618:     if (drills > 1) {
619:       ctx.font = `700 ${9 / s}px ${'ui-monospace, monospace'}`;
620:       ctx.fillStyle = 'rgba(232,225,207,0.55)';
621:       ctx.textAlign = 'center';
622:       ctx.fillText(`×${drills}`, 0, -76);
623:       ctx.textAlign = 'left';
624:     }
625:     ctx.restore();
626:   }
627: 
628:   drawCritter(ctx, t) {
629:     const cycle = (t * 0.18) % 1;
630:     const x = cycle * (this.w + 100) - 50;
631:     if (x < -20 || x > this.w + 20) return;
632:     const y = this.floorY + 10;
633:     const s = this.scale * 0.42;
634:     ctx.save();
635:     ctx.globalAlpha = 0.4;
636:     ctx.translate(x, y);
637:     ctx.scale(s, s);
638:     ctx.fillStyle = '#0c0d0a';
639:     ctx.beginPath(); ctx.ellipse(0, -8, 11, 5, 0, 0, TAU); ctx.fill();
640:     ctx.beginPath(); ctx.arc(-10, -11, 4, 0, TAU); ctx.fill();
641:     // tail
642:     ctx.strokeStyle = '#0c0d0a'; ctx.lineWidth = 1.5;
643:     ctx.beginPath(); ctx.moveTo(10, -9); ctx.quadraticCurveTo(17, -16 + Math.sin(t * 10) * 3, 22, -8); ctx.stroke();
644:     // legs
645:     ctx.lineWidth = 2;
646:     for (let i = 0; i < 3; i++) {
647:       const off = Math.sin(t * 16 + i * 2) * 2;
648:       ctx.beginPath();
649:       ctx.moveTo(-6 + i * 6, -5);
650:       ctx.lineTo(-6 + i * 6 + off, 0);
651:       ctx.stroke();
652:     }
653:     // eye
654:     ctx.fillStyle = '#ffb15c';
655:     ctx.beginPath(); ctx.arc(-12, -12, 0.9, 0, TAU); ctx.fill();
656:     ctx.restore();
657:   }
658: 
659:   drawVein(ctx, t, layer, state, layerIndex, node, key) {
660:     if (this.veinHidden > 0) return;
661:     const { veinX: cx, veinY: cy, scale: s } = this;
662:     const hp = state.veinHp?.[layerIndex] ?? layer.hp;
663:     const maxHp = layerMaxHp(state, layerIndex);
664:     const dmg = clamp(1 - hp / Math.max(1, maxHp), 0, 1);
665:     const pulse = 0.82 + Math.sin(t * 2.3) * 0.18;
666:     const rich = 1 + 0.02 * node;
667: 
668:     ctx.save();
