2020:   drawCombatWeapon(ctx, visual, x, y, angle, len, trim, atk) {
2021:     ctx.save();
2022:     ctx.translate(x, y);
2023:     ctx.rotate(angle);
2024:     const isGun = ['pistol', 'smg', 'shotgun', 'rifle', 'mg', 'railgun'].includes(visual);
2025: 
2026:     if (isGun) {
2027:       // stock, receiver, grip, barrel — silhouettes differ per gun class
2028:       ctx.fillStyle = '#3b3a31';
2029:       const bodyEnd = visual === 'pistol' ? len * 0.52 : len * 0.58;
2030:       const bodyH = visual === 'mg' ? 8 : visual === 'shotgun' ? 6 : 5;
2031:       // stock
2032:       if (visual !== 'pistol') {
2033:         ctx.fillStyle = '#2a271e';
2034:         ctx.beginPath();
2035:         ctx.moveTo(-9, -2.5);
2036:         ctx.lineTo(0, -bodyH / 2);
2037:         ctx.lineTo(0, bodyH / 2);
2038:         ctx.lineTo(-9, 3.5);
2039:         ctx.closePath();
2040:         ctx.fill();
2041:       }
2042:       // receiver
2043:       ctx.fillStyle = '#3b3a31';
2044:       ctx.fillRect(0, -bodyH / 2, bodyEnd, bodyH);
2045:       ctx.strokeStyle = 'rgba(255,255,255,0.18)';
2046:       ctx.lineWidth = 0.8;
2047:       ctx.strokeRect(0, -bodyH / 2, bodyEnd, bodyH);
2048:       // barrel
2049:       ctx.fillStyle = visual === 'railgun' ? '#4a4058' : '#25261f';
2050:       const barrelH = visual === 'mg' ? 3.6 : visual === 'shotgun' ? 3 : 2.2;
2051:       ctx.fillRect(bodyEnd, -barrelH / 2, len - bodyEnd, barrelH);
2052:       // grip
2053:       ctx.fillStyle = '#29261d';
2054:       ctx.fillRect(visual === 'pistol' ? 3 : 5, bodyH / 2, 4, 8);
2055:       // trigger guard
2056:       ctx.strokeStyle = '#1c1d17';
2057:       ctx.lineWidth = 1;
2058:       ctx.beginPath();
2059:       ctx.arc(visual === 'pistol' ? 6 : 8, bodyH / 2 + 4, 3, 0, Math.PI);
2060:       ctx.stroke();
2061:       // magazine / belt box
2062:       if (visual === 'smg' || visual === 'rifle') {
2063:         ctx.fillStyle = '#2b2d24';
2064:         ctx.fillRect(bodyEnd * 0.45, bodyH / 2, 5, visual === 'smg' ? 12 : 8);
2065:       }
2066:       if (visual === 'mg') {
2067:         ctx.fillStyle = '#3a3d31';
2068:         ctx.fillRect(bodyEnd * 0.32, bodyH / 2 + 1, 11, 8);
2069:         ctx.strokeStyle = '#c7a85a';
2070:         ctx.lineWidth = 1;
2071:         for (let i = 0; i < 4; i++) {
2072:           ctx.beginPath();
2073:           ctx.moveTo(bodyEnd * 0.35 + i * 2.2, bodyH / 2 + 2);
2074:           ctx.lineTo(bodyEnd * 0.35 + i * 2.2, bodyH / 2 + 8);
2075:           ctx.stroke();
2076:         }
2077:         // bipod
2078:         ctx.strokeStyle = '#2a2c24';
2079:         ctx.lineWidth = 1.4;
2080:         ctx.beginPath();
2081:         ctx.moveTo(bodyEnd + 2, 1);
2082:         ctx.lineTo(bodyEnd + 6, 9);
2083:         ctx.moveTo(bodyEnd + 2, -1);
2084:         ctx.lineTo(bodyEnd + 6, -9);
2085:         ctx.stroke();
2086:       }
2087:       // sights / scope
2088:       if (visual === 'rifle' || visual === 'railgun') {
