2253:   /* ── enemy art ───────────────────────────────────────────── */
2254:   drawEnemy(ctx, enemy, zone, zoneIndex, t, x, y, scale, spawnAge) {
2255:     const boss = enemy.boss;
2256:     const s = scale * (boss ? 1.32 : 1);
2257:     const idle = Math.sin(t * 2 + zoneIndex) * (boss ? 2 : 1.4);
2258:     const flash = this.enemyFlash;
2259:     const atk = this.enemyAtk;
2260:     const lunge = atk < 1 ? Math.sin(Math.PI * atk) : 0;
2261:     const appearance = enemy.name.includes('Hound') || enemy.name.includes('Dog') || enemy.name.includes('Rat')
2262:       ? 'critter' : zone.shape;
2263: 
2264:     ctx.save();
2265:     ctx.translate(x, y + idle * 0.4);
2266:     ctx.scale(-s, s); // face left
2267:     ctx.globalAlpha *= 1;
2268:     if (boss) {
2269:       // crown / spikes behind
2270:       ctx.save();
2271:       ctx.fillStyle = rgba(zone.accent, 0.2);
2272:       ctx.beginPath();
2273:       ctx.moveTo(-24, -94); ctx.lineTo(-16, -112); ctx.lineTo(-7, -98); ctx.lineTo(2, -118); ctx.lineTo(11, -98); ctx.lineTo(21, -112); ctx.lineTo(25, -94);
2274:       ctx.closePath();
2275:       ctx.fill();
2276:       ctx.restore();
2277:     }
2278: 
2279:     if (appearance === 'critter') this.drawCritterEnemy(ctx, t, flash, atk, zone, boss);
2280:     else if (appearance === 'raider') this.drawRaiderEnemy(ctx, t, flash, atk, zone, boss);
2281:     else if (appearance === 'golem') this.drawGolemEnemy(ctx, t, flash, atk, zone, boss);
2282:     else if (appearance === 'brute') this.drawBruteEnemy(ctx, t, flash, atk, zone, boss);
2283:     else if (appearance === 'sentry') this.drawSentryEnemy(ctx, t, flash, atk, zone, boss);
2284:     else this.drawVoidEnemy(ctx, t, flash, atk, zone, boss);
2285: 
2286:     // hit flash overlay
2287:     if (flash > 0.03) {
2288:       ctx.globalCompositeOperation = 'lighter';
2289:       ctx.fillStyle = `rgba(255,120,90,${0.14 * flash})`;
2290:       ctx.beginPath();
2291:       ctx.arc(0, -50, 46, 0, TAU);
2292:       ctx.fill();
2293:       ctx.globalCompositeOperation = 'source-over';
2294:     }
2295:     ctx.restore();
2296: 
2297:     if (lunge > 0.4 && atk < 0.55) {
2298:       // swipe
2299:       ctx.save();
2300:       ctx.translate(x - 24 * s, y - 44 * s);
2301:       ctx.strokeStyle = `rgba(255,150,120,${0.5 * (1 - atk / 0.55)})`;
2302:       ctx.lineWidth = 2.4;
2303:       ctx.beginPath();
2304:       ctx.arc(0, 0, 30 * s, -1.2, 0.9);
2305:       ctx.stroke();
2306:       ctx.restore();
2307:     }
2308:   }
