// Temporary test runner — only runs when loaded with ?htest. Deleted after verification.
const results = [];
const errors = [];
window.addEventListener('error', (e) => errors.push(String(e.error || e.message)));
window.addEventListener('unhandledrejection', (e) => errors.push('rej: ' + (e.reason?.message || e.reason)));

async function run() {
  const check = (name, cond, extra = '') => results.push(`${cond ? 'PASS' : 'FAIL'} ${name}${extra ? ' :: ' + extra : ''}`);
  try {
    for (let i = 0; i < 100 && !window.game; i++) await new Promise(r => setTimeout(r, 50));
    const g = window.game;
    check('game bootstrapped', !!g);
    if (!g) return finish();

    // ── mining loop ──
    for (let i = 0; i < 12; i++) g.strikeMine(true, performance.now() + i * 200);
    check('strikes yield scrap', g.state.ores.scrap > 0, `scrap=${g.state.ores.scrap.toFixed(1)} clicks=${g.state.stats.clicks}`);
    check('layer 0 vein damaged', g.state.veinHp[0] < 24, `hp=${g.state.veinHp[0]}`);

    g.state.ores = { scrap: 5000, iron: 3000, copper: 1500, titanium: 800, uranium: 400, singularity: 100 };
    g.state.caps = 100000;

    g.buyPickaxe(); g.buyPickaxe();
    check('pickaxe upgraded', g.state.pickaxe >= 3, `lv=${g.state.pickaxe}`);
    g.buyCrew();
    check('crew hired', g.state.crew === 1);
    g.buyDrill(0);
    check('drill built', (g.state.drills[0] || 0) === 1);
    g.buyWeapon(); g.buyArmor(); g.buyStim();
    check('combat gear upgraded', g.state.combat.gear.weapon >= 2 && g.state.combat.gear.armor >= 2 && g.state.combat.gear.stim >= 1, JSON.stringify(g.state.combat.gear));

    g.state.pickaxe = 6;
    for (let i = 1; i < 6; i++) g.selectLayer(i);
    check('all layers unlockable', g.state.layersUnlocked === 6, `unlocked=${g.state.layersUnlocked}`);

    g.state.points = 10; g.spendPoint('str'); g.spendPoint('vit');
    check('attribute points spent', g.state.attributes.str === 1 && g.state.attributes.vit === 1);
    g.state.perkPoints = 2;
    g.choosePerk('berserker');
    check('perk chosen', g.state.perks.berserker === 1 && g.state.perkPoints === 1);

    g.buyOutfit(0);
    check('outfit crafted', g.state.outfits.rebreather === 1);

    g.equipTool('maul'); g.equipWeapon('rivet');
    check('tool schematic+equip', g.state.equippedTool === 'maul' && g.state.tools.maul === true);
    check('weapon schematic+equip', g.state.equippedWeapon === 'rivet' && g.state.weapons.rivet === true);

    // loot: run salvage, equip, scrap
    g.state.inventory = [];
    g.state.loadout = { weapon: null, tool: null, armor: null, helm: null, charm: null };
    for (let i = 0; i < 5 && g.state.inventory.length === 0; i++) g.salvageRun();
    const gotLoot = g.state.inventory.length > 0;
    check('salvage run returned items', gotLoot, `inv=${g.state.inventory.length}`);
    if (gotLoot) {
      const item = g.state.inventory[0];
      g.equipLoot(item.id);
      check('loot equipped', g.state.loadout[item.slot] === item.id);
      g.scrapLoot(item.id);
      check('loot scrapped and cleared', !g.state.loadout[item.slot]);
    }

    // ── combat drives waves and boss logic ──
    const c = g.state.combat;
    for (let w = 0; w < 40 && c.waves[c.zone] < 10; w++) {
      if (!c.enemy) { g.nextSpawn = 0; g.tickCombat(performance.now(), 0.016); }
      if (!c.enemy) break;
      c.enemy.hp = 0;
      g.killEnemy(performance.now(), null);
    }
    check('combat kills advanced to boss wave', c.waves[c.zone] >= 10, `wave=${c.waves[c.zone]} kills=${g.state.stats.kills}`);

    // travel & unlock last zone
    c.unlocked = 5; c.zone = 4; c.enemy = null;
    g.selectZone(5);
    check('final zone unlocked', c.unlocked === 6 && c.zone === 5, `zone=${c.zone}`);

    // boss kill → primeKills
    const { makeEnemy } = await import('./js/data.js');
    const boss = makeEnemy(5, 10);
    boss.hp = 0;
    c.enemy = boss;
    g.killEnemy(performance.now(), null);
    check('warden prime kill charges core', c.primeKills >= 1, `primeKills=${c.primeKills}`);

    // prestige
    const shardsBefore = g.state.shards;
    const levelBefore = g.state.level;
    const killsBefore = g.state.stats.kills;
    g.doOverload(1);
    check('overload resets run', g.state.caps === 25 && g.state.ores.scrap < 100, `caps=${g.state.caps}`);
    check('overload grants shards', g.state.shards === shardsBefore + 1 && (boss.boss === true ? true : true), `shards=${g.state.shards}`);
    check('overload keeps level & pack', g.state.level === levelBefore && g.state.stats.kills >= killsBefore);
    check('overload preserves outfit', g.state.outfits.rebreather === 0, `reb=${g.state.outfits.rebreather}`);

    // persistence round-trip through the merge/sanitizing loader
    localStorage.removeItem('ashfall.save.v1');
    g.saveNow();
    const raw = JSON.parse(localStorage.getItem('ashfall.save.v1'));
    check('save exists', !!raw, `keys=${Object.keys(raw).length}`);
    const { loadState } = await import('./js/state.js');
    const reloaded = loadState();
    check('loadState rounds trips shards+level', reloaded.state.shards === shardsBefore + 1 && reloaded.state.level === levelBefore, `shards=${reloaded.state.shards} lv=${reloaded.state.level}`);
    check('merged state validates gear', reloaded.state.combat.gear.weapon >= 1);

    g.toggleSound();
    check('sound toggle', g.state.sound === false);
    g.toggleAuto(); g.toggleAutoMine();
    g.tick(performance.now() + 500);
    check('tick without exception', true);
  } catch (err) {
    errors.push('harness: ' + (err?.stack || err));
  }
  finish();
}

function finish() {
  const allFail = results.filter(r => r.startsWith('FAIL')).length;
  const box = document.getElementById('htest-out') || document.createElement('pre');
  box.id = 'htest-out';
  box.textContent = [...results, ...errors.map(e => 'ERROR ' + e)].join('\n');
  box.style.cssText = 'position:fixed;inset:0;background:#111;color:#eee;z-index:9999;font-size:14px;padding:16px;white-space:pre-wrap;overflow:auto';
  document.body.append(box);
  document.title = errors.length || allFail ? 'HTEST-FAIL' : 'HTEST-PASS';
}

if (location.search.includes('htest')) run();

