input.newString:
if (location.search.includes('htest2')) {
  setTimeout(() => {
    try {
      const mine = window.game?.mineRenderer;
      const c = mine?.canvas;
      const ctx = c?.getContext('2d');
      let sum = 0, n = 0, max = 0;
      if (ctx) {
        const img = ctx.getImageData(0, 0, 320, Math.max(1, Math.round(c.height / (mine.dpr || 2))));
        for (let i = 0; i < img.data.length; i += 40) {
          const v = (img.data[i] + img.data[i + 1] + img.data[i + 2]) / 3;
          sum += v; n++; max = Math.max(max, v);
        }
      }
      document.title = `dims=${mine?.w}x${mine?.h} avg=${(sum / Math.max(1, n)).toFixed(1)} max=${max.toFixed(0)} par=${mine?.particles.length}`;
    } catch (err) {
      document.title = 'PIXERR ' + err.message;
    }
  }, 2500);
}

